class MazeApi:
    def __init__(self, edges, start, goal):
        self.edges = edges
        self.position = start
        self.goal = goal
        self.moves = []
        self.neighbor_queries = []
        self._advertised = {}

    def current(self):
        return self.position

    def neighbors(self):
        self.neighbor_queries.append(self.position)
        self._advertised = dict(self.edges.get(self.position, {}))
        return dict(self._advertised)

    def move(self, direction):
        assert direction in self._advertised
        self.position = self._advertised[direction]
        self.moves.append(direction)
        self._advertised = {}

    def is_goal(self):
        return self.position == self.goal

edges = {
    (0, 0): {'E': (0, 1), 'S': (1, 0)},
    (0, 1): {'W': (0, 0), 'S': (1, 1)},
    (1, 0): {'N': (0, 0)},
    (1, 1): {'N': (0, 1)}
}
api = MazeApi(edges, (0, 0), (1, 1))
route = find_route(api)
assert route is not None
assert route[0] == (0, 0) and route[-1] == (1, 1)
assert api.position == (1, 1)
assert api.moves
assert set(api.neighbor_queries) <= set(edges)

class MazeApi:
    def __init__(self):
        self.edges = {
            (0, 0): {'E': (0, 1)},
            (0, 1): {'W': (0, 0), 'E': (0, 2)},
            (0, 2): {'W': (0, 1)}
        }
        self.position = (0, 0)
        self.moves = []
        self._advertised = {}

    def current(self):
        return self.position

    def neighbors(self):
        self._advertised = dict(self.edges.get(self.position, {}))
        return dict(self._advertised)

    def move(self, direction):
        assert direction in self._advertised
        self.position = self._advertised[direction]
        self.moves.append(direction)
        self._advertised = {}

    def is_goal(self):
        return False

api = MazeApi()
assert find_route(api) is None
assert api.position == (0, 0)
assert api.moves.count('E') == 2 and api.moves.count('W') == 2

class StartGoalApi:
    def current(self):
        return (4, 7)

    def neighbors(self):
        raise AssertionError('neighbors should not be queried')

    def move(self, direction):
        raise AssertionError('move should not be called')

    def is_goal(self):
        return True

assert find_route(StartGoalApi()) == [(4, 7)]
